cd /tmp && cat > probe.mjs <<'EOF'
const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
function polymod(values){let chk=1;for(const v of values){const top=chk>>>25;chk=((chk&0x1ffffff)<<5)^v;for(let i=0;i<5;i++)if((top>>i)&1)chk^=GEN[i];}return chk>>>0;}
function hrpExpand(hrp){const a=[],b=[];for(const ch of hrp){a.push(ch.codePointAt(0)>>5);b.push(ch.codePointAt(0)&31);}return a.concat([0],b);}
function checksum(hrp,data,cst){const v=hrpExpand(hrp).concat(data,[0,0,0,0,0,0]);const pm=(polymod(v)^cst)>>>0;const out=[];for(let i=0;i<6;i++)out.push((pm>>>(5*(5-i)))&31);return out;}
function conv(data,fb,tb,pad=true){let acc=0,bits=0;const ret=[];const maxv=(1<<tb)-1,maxacc=(1<<(fb+tb-1))-1;for(const value of data){if(value<0||(value>>fb))return null;acc=((acc<<fb)|value)&maxacc;bits+=fb;while(bits>=tb){bits-=tb;ret.push((acc>>bits)&maxv);}}if(pad){if(bits)ret.push((acc<<(tb-bits))&maxv);}else if(bits>=fb||((acc<<(tb-bits))&maxv))return null;return ret;}
function enc(hrp,witver,prog,cst){const d=[witver].concat(conv(prog,8,5));return hrp+'1'+d.concat(checksum(hrp,d,cst)).map(x=>CHARSET[x]).join('');}
const W=[]; for(let i=1;i<=20;i++)W.push(i);
const W32=[]; for(let i=1;i<=32;i++)W32.push(i);
const BECH32=1, BECH32M=0x2bc830a3;
console.log('v0  bech32 :', enc('bc',0,W,BECH32),  '| expect bc1qqypqxpq9qcrsszg2pvxq6rs0zqg3yyc5fcj4z3');
console.log('v0  bech32m:', enc('bc',0,W,BECH32M));
console.log('v5  bech32 :', enc('bc',5,W,BECH32),  '| expect bc19qypqxpq9qcrsszg2pvxq6rs0zqg3yyc589tmjl');
console.log('v5  bech32m:', enc('bc',5,W,BECH32M));
console.log('v16 bech32 :', enc('bc',16,W,BECH32), '| expect bc1sqypqxpq9qcrsszg2pvxq6rs0zqg3yyc5a5rpd9');
console.log('v16 bech32m:', enc('bc',16,W,BECH32M));
console.log('t1  bech32 :', enc('test',13,[26,9,19,24,11,30,15,14,19,9,29,3,26,26,8,24,15,16,13,21,5,28,23,5,12,3,17,24,2,4,12,13],BECH32), '| expect test1drgy3xxqtrc8suycfr5p35xsgrq83qrg4q5wpwpgvqvg3sqsypsxszulw0v');
EOF
node probe.mjs

cd /tmp && cat > nd.mjs <<'EOF'
const re = /\p{Nd}/u;
const cps = [];
for (let cp = 0; cp <= 0x10FFFF; cp++) {
  if (cp >= 0xD800 && cp <= 0xDFFF) continue;
  if (re.test(String.fromCodePoint(cp))) cps.push(cp);
}
// group into consecutive runs
const runs = [];
for (const cp of cps) {
  const last = runs[runs.length-1];
  if (last && cp === last[1] + 1) last[1] = cp; else runs.push([cp, cp]);
}
const bases = [];
let bad = [];
for (const [s,e] of runs) {
  const len = e - s + 1;
  if (len % 10 !== 0) bad.push([s.toString(16), e.toString(16), len]);
  for (let b = s; b <= e; b += 10) bases.push(b);
}
console.log('total Nd:', cps.length, 'runs:', runs.length, 'bases:', bases.length);
console.log('non-multiple-of-10 runs:', JSON.stringify(bad));
console.log('bases hex:', bases.map(b=>b.toString(16)).join(','));
EOF
node nd.mjs

