/**
 * `convertbits`: general power-of-two base conversion over a list of integers.
 *
 * Values stay BigInt so that an out-of-range witness program byte is rejected by
 * the same `value >> frombits` test Python applies, whatever its magnitude.
 * A rejected input yields `null`, mirroring the Python return value.
 */

export function convertBits(data, fromBits, toBits, pad = true) {
  const from = BigInt(fromBits);
  const to = BigInt(toBits);
  const maxValue = (1n << to) - 1n;
  const maxAccumulator = (1n << (from + to - 1n)) - 1n;

  let accumulator = 0n;
  let bits = 0n;
  const result = [];

  for (const value of data) {
    if (value < 0n || (value >> from) !== 0n) return null;
    accumulator = ((accumulator << from) | value) & maxAccumulator;
    bits += from;
    while (bits >= to) {
      bits -= to;
      result.push((accumulator >> bits) & maxValue);
    }
  }

  if (pad) {
    if (bits !== 0n) result.push((accumulator << (to - bits)) & maxValue);
  } else if (bits >= from || ((accumulator << (to - bits)) & maxValue) !== 0n) {
    return null;
  }

  return result;
}

