// Differential harness: runs the reference executable and the Node port on the
// same argv and compares stdout, stderr (PID-normalized) and exit code.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test4_executable';
const PORT = ['/output/test4.mjs'];

function norm(s) {
  return s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

export function runCase(argv) {
  const a = spawnSync(REF, argv, { encoding: 'utf8' });
  const b = spawnSync('node', [...PORT, ...argv], { encoding: 'utf8' });
  const ok =
    a.stdout === b.stdout &&
    norm(a.stderr) === norm(b.stderr) &&
    a.status === b.status;
  return { ok, argv, ref: { out: a.stdout, err: norm(a.stderr), code: a.status },
           port: { out: b.stdout, err: norm(b.stderr), code: b.status } };
}

export function runAll(cases, { label = '', quiet = false } = {}) {
  let pass = 0;
  const fails = [];
  for (const argv of cases) {
    const r = runCase(argv);
    if (r.ok) pass++;
    else fails.push(r);
  }
  if (!quiet) {
    console.log(`${label} pass=${pass}/${cases.length} fail=${fails.length}`);
    for (const f of fails.slice(0, 25)) {
      console.log('MISMATCH argv=' + JSON.stringify(f.argv));
      console.log('  ref : code=' + f.ref.code + ' out=' + JSON.stringify(f.ref.out) + ' err=' + JSON.stringify(f.ref.err));
      console.log('  port: code=' + f.port.code + ' out=' + JSON.stringify(f.port.out) + ' err=' + JSON.stringify(f.port.err));
    }
  }
  return { pass, total: cases.length, fails };
}

// CLI: node difftest.mjs cases.json
if (process.argv[2]) {
  const { readFileSync } = await import('node:fs');
  const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
  const { fails } = runAll(cases, { label: process.argv[2] });
  process.exit(fails.length ? 1 : 0);
}

