      console.log('  ref : code=' + f.ref.code + ' out=' + JSON.stringify(f.ref.out) + ' err=' + JSON.stringify(f.ref.err));
      console.log('  port: code=' + f.port.code + ' out=' + JSON.stringify(f.port.out) + ' err=' + JSON.stringify(f.port.err));
    }
  }
  return { pass, total: cases.length, fails };
}

