/**
 * A small `linecache` equivalent.
 *
 * CPython renders traceback source lines by reading the file named in the frame
 * at display time, resolving a relative name against the current working
 * directory.  The frozen reference build ships no sources, so its tracebacks
 * show source text only when a matching file happens to sit next to the caller
 * -- and omit those lines entirely otherwise.  Reproducing that means doing the
 * same lookup rather than embedding the source.
 */

import { readFileSync } from 'node:fs';

const cache = new Map();

/** Splits text into lines that keep their trailing newline, as `readlines()` does. */
function splitKeepingNewlines(text) {
  const lines = [];
  let start = 0;
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] === '\n') {
      lines.push(text.slice(start, index + 1));
      start = index + 1;
    }
  }
  if (start < text.length) lines.push(text.slice(start));
  return lines;
}

function readLines(filename) {
  let text;
  try {
    text = readFileSync(filename, 'utf8');
  } catch {
    // Missing, unreadable, or a directory: the frame shows no source.
    return [];
  }
  // `tokenize.open()` applies universal newlines.
  return splitKeepingNewlines(text.replace(/\r\n?/g, '\n'));
}

/** `linecache.getline`: 1-based, `''` when the line is unavailable. */
export function getLine(filename, lineNumber) {
  let lines = cache.get(filename);
  if (lines === undefined) {
    lines = readLines(filename);
    cache.set(filename, lines);
  }
  if (lineNumber < 1 || lineNumber > lines.length) return '';
  return lines[lineNumber - 1];
}

