/**
 * Traceback rendering for the frozen `test4` script.
 *
 * An unhandled exception in the reference build prints a CPython traceback
 * followed by PyInstaller's one-line summary.  Each frame contributes a location
 * line; a source line and its `^^^^` anchor line follow only when the named file
 * can be read from the current directory (see ./linecache.mjs).  The anchor
 * columns come from the compiled code objects -- they are properties of the code
 * that was frozen, not of whatever file is found on disk -- so they are recorded
 * here as byte offsets into the original source lines.
 */

import { getLine } from './linecache.mjs';
import { isPythonSpace } from './unicode.mjs';
import { writeStderr } from './stdio.mjs';

const SCRIPT_MODULE = 'test4';
const SCRIPT_FILE = 'test4.py';
const LIBRARY_FILE = 'bech32/__init__.py';
const INDENT = '    ';

const MODULE_FRAME = { file: SCRIPT_FILE, line: 16, name: '<module>', colno: 4, endColno: 10 };

/** `witprog = list(map(int, args.c.split(',')))` raised while converting `--c`. */
export const CONVERT_ARGUMENT_FRAMES = [
  MODULE_FRAME,
  { file: SCRIPT_FILE, line: 11, name: 'main', colno: 14, endColno: 47 },
];

/** `result = bech32.encode(...)` raised inside the packaged bech32 module. */
export const ENCODE_FRAMES = [
  MODULE_FRAME,
  { file: SCRIPT_FILE, line: 12, name: 'main', colno: 13, endColno: 51 },
  { file: LIBRARY_FILE, line: 127, name: 'encode', colno: 10, endColno: 57 },
  { file: LIBRARY_FILE, line: 61, name: 'bech32_encode', colno: 32, endColno: 42 },
];

const codePoints = (text) => Array.from(text);

function utf8Size(codePoint) {
  if (codePoint < 0x80) return 1;
  if (codePoint < 0x800) return 2;
  if (codePoint < 0x10000) return 3;
  return 4;
}

/**
 * `_byte_offset_to_character_offset`: how many characters of `text` fit in its
 * first `byteOffset` UTF-8 bytes.  Offsets past the end clamp to the whole line,
 * which is what makes the anchors shrink when the file on disk is shorter than
 * the source that was compiled.
 */
function byteOffsetToCharOffset(text, byteOffset) {
  let bytes = 0;
  let characters = 0;
  for (const character of text) {
    const size = utf8Size(character.codePointAt(0));
    if (bytes + size > byteOffset) break;
    bytes += size;
    characters += 1;
  }
  return characters;
}

function stripPythonWhitespace(text) {
  const characters = codePoints(text);
  let start = 0;
  let end = characters.length;
  while (start < end && isPythonSpace(characters[start].codePointAt(0))) start += 1;
  while (end > start && isPythonSpace(characters[end - 1].codePointAt(0))) end -= 1;
  return characters.slice(start, end).join('');
}

function leadingWhitespaceCount(text) {
  let count = 0;
  for (const character of text) {
    if (!isPythonSpace(character.codePointAt(0))) break;
    count += 1;
  }
  return count;
}

function frameLines(frame) {
  const lines = [`  File "${frame.file}", line ${frame.line}, in ${frame.name}`];

  const rawLine = getLine(frame.file, frame.line);
  const stripped = stripPythonWhitespace(rawLine);
  if (stripped === '') return lines;
  lines.push(`${INDENT}${stripped}`);

  const start = byteOffsetToCharOffset(rawLine, frame.colno);
  const end = byteOffsetToCharOffset(rawLine, frame.endColno);
  const strippedLength = codePoints(stripped).length;
  // Anchors are suppressed when they would span the whole statement.
  if (end - start >= strippedLength) return lines;

  const gap = Math.max(0, start - leadingWhitespaceCount(rawLine));
  const width = Math.max(0, end - start);
  lines.push(`${INDENT}${' '.repeat(gap)}${'^'.repeat(width)}`);
  return lines;
}

/**
 * Prints the traceback for an unhandled exception exactly as the frozen build
 * does, including PyInstaller's trailing failure notice.
 */
export function reportUnhandledException(error, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) lines.push(...frameLines(frame));
  lines.push(`${error.typeName}: ${error.pythonMessage}`);
  lines.push(
    `[PYI-${process.pid}:ERROR] Failed to execute script '${SCRIPT_MODULE}' due to unhandled exception!`,
  );
  writeStderr(`${lines.join('\n')}\n`);
}

