/**
 * The slice of `argparse.ArgumentParser` this script depends on.
 *
 * Reproduced from observed behaviour of the reference build (CPython 3.11+
 * argparse): usage/help layout, the `--x=value` form, long-option abbreviation,
 * the negative-number heuristic that lets `--b -1` pass a value through, `--`
 * ending option parsing, and the three error messages (`expected one argument`,
 * `invalid <type> value`, `the following arguments are required`) which all exit
 * with status 2 after printing usage.
 */

import { writeStdout, writeStderr } from './stdio.mjs';
import { pythonRepr } from './repr.mjs';
import { PythonError } from './errors.mjs';

const PREFIX = '-';
const HELP_INVOCATION = '-h, --help';
const HELP_TEXT = 'show this help message and exit';
const INDENT = 2;
const MAX_HELP_POSITION = 24;

/**
 * argparse's `_negative_number_matcher`.  Python's `\d` covers every Unicode
 * decimal digit, hence `\p{Nd}` rather than `[0-9]`.
 */
const NEGATIVE_NUMBER = new RegExp(
  '^-\\p{Nd}+$|^-\\p{Nd}*\\.\\p{Nd}+$',
  'u',
);

class Action {
  constructor(optionStrings, { dest, metavar, type, typeName, required, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.metavar = metavar;
    this.type = type;
    this.typeName = typeName;
    this.required = required === true;
    this.isHelp = isHelp === true;
  }

  /** `_get_action_name`: how the action is named inside error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** `_format_action_invocation`: `-h, --help` / `--a A`. */
  get invocation() {
    if (this.isHelp) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  /** `_format_actions_usage`: the usage line names only the first option string. */
  get usagePart() {
    const option = this.optionStrings[0];
    return this.isHelp ? option : `${option} ${this.metavar}`;
  }
}

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionMap = new Map();
    this.#register(
      new Action(['-h', '--help'], { dest: 'help', isHelp: true, required: false }),
    );
  }

  #register(action) {
    this.actions.push(action);
    for (const option of action.optionStrings) this.optionMap.set(option, action);
    return action;
  }

  /**
   * `add_argument("--x", type=..., required=...)`.  `type` is a converter that
   * throws for invalid input; `typeName` is the `__name__` argparse reports.
   */
  add_argument(optionString, { type, typeName, required } = {}) {
    const dest = optionString.replace(/^-+/, '').replace(/-/g, '_');
    return this.#register(
      new Action([optionString], {
        dest,
        metavar: dest.toUpperCase(),
        type,
        typeName: typeName ?? 'str',
        required,
      }),
    );
  }

  format_usage() {
    const parts = this.actions.map((action) =>
      action.required ? action.usagePart : `[${action.usagePart}]`,
    );
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  format_help() {
    // HelpFormatter aligns help text at `min(longest + 2, 24)` columns, where
    // `longest` already includes the two-space action indent.
    const longest = Math.max(
      ...this.actions.map((action) => action.invocation.length + INDENT),
    );
    const helpPosition = Math.min(longest + 2, MAX_HELP_POSITION);
    const invocationWidth = helpPosition - INDENT - 2;

    const lines = [this.format_usage().trimEnd(), '', 'options:'];
    for (const action of this.actions) {
      const invocation = action.invocation;
      if (!action.isHelp) {
        lines.push(`${' '.repeat(INDENT)}${invocation}`);
        continue;
      }
      lines.push(
        `${' '.repeat(INDENT)}${invocation.padEnd(invocationWidth)}  ${HELP_TEXT}`,
      );
    }
    return `${lines.join('\n')}\n`;
  }

  /** Prints usage plus the message on stderr and exits with status 2. */
  error(message) {
    writeStderr(this.format_usage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  print_help() {
    writeStdout(this.format_help());
  }

  parse_args(argv) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parse_known_args(argv) {
    const namespace = Object.create(null);
    const seen = new Set();
    const extras = [];
    let index = 0;
    let optionsEnded = false;

    while (index < argv.length) {
      const argument = argv[index];

      if (optionsEnded) {
        extras.push(argument);
        index += 1;
        continue;
      }
      // A bare `--` stops option parsing; argparse leaves it among the leftovers.
      if (argument === '--') {
        extras.push(argument);
        optionsEnded = true;
        index += 1;
        continue;
      }

      const candidate = this.#parseOptional(argument);
      if (candidate === null || candidate.action === null) {
        // Either a positional-looking token or an unknown option: both survive
        // as leftovers for `unrecognized arguments`.
        extras.push(argument);
        index += 1;
        continue;
      }

      const { action, optionString, explicitArgument } = candidate;
      if (action.isHelp) {
        // A `--help=x` form reaches an action that takes no argument.
        if (explicitArgument !== null) {
          this.error(
            `argument ${action.name}: ignored explicit argument ${pythonRepr(explicitArgument)}`,
          );
        }
        this.print_help();
        process.exit(0);
      }

      let rawValue;
      if (explicitArgument !== null) {
        rawValue = explicitArgument;
        index += 1;
      } else {
        const next = index + 1 < argv.length ? argv[index + 1] : null;
        if (next === null || next === '--' || this.#parseOptional(next) !== null) {
          this.error(`argument ${action.name}: expected one argument`);
        }
        rawValue = next;
        index += 2;
      }

      namespace[action.dest] = this.#convert(action, rawValue);
      seen.add(action.dest);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.name);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  #convert(action, rawValue) {
    if (action.type === undefined) return rawValue;
    try {
      return action.type(rawValue);
    } catch (error) {
      if (error instanceof PythonError || error instanceof TypeError) {
        this.error(
          `argument ${action.name}: invalid ${action.typeName} value: ${pythonRepr(rawValue)}`,
        );
      }
      throw error;
    }
  }

  /**
   * `_parse_optional`.  Returns `null` when the token should be treated as a
   * value, `{action: null, ...}` when it looks like an unknown option, and a
   * resolved action otherwise.
   */
  #parseOptional(argument) {
    if (argument.length === 0) return null;
    if (argument[0] !== PREFIX) return null;

    const exact = this.optionMap.get(argument);
    if (exact !== undefined) {
      return { action: exact, optionString: argument, explicitArgument: null };
    }
    // A lone `-` was meant to be positional.
    if (argument.length === 1) return null;

    const equals = argument.indexOf('=');
    if (equals >= 0) {
      const optionString = argument.slice(0, equals);
      const action = this.optionMap.get(optionString);
      if (action !== undefined) {
        return { action, optionString, explicitArgument: argument.slice(equals + 1) };
      }
    }

    const matches = this.#optionTuples(argument);
    if (matches.length > 1) {
      const options = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argument} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];

    // Negative numbers are values, since no option string looks like one.
    if (NEGATIVE_NUMBER.test(argument)) return null;
    // Anything containing a space cannot be an option.
    if (argument.includes(' ')) return null;

    return { action: null, optionString: argument, explicitArgument: null };
  }

  /** `_get_option_tuples`: abbreviation matching. */
  #optionTuples(argument) {
    const matches = [];
    if (argument.startsWith('--')) {
      const equals = argument.indexOf('=');
      const prefix = equals >= 0 ? argument.slice(0, equals) : argument;
      const explicitArgument = equals >= 0 ? argument.slice(equals + 1) : null;
      for (const [optionString, action] of this.optionMap) {
        if (optionString.startsWith(prefix)) {
          matches.push({ action, optionString, explicitArgument });
        }
      }
      return matches;
    }

    const shortPrefix = argument.slice(0, 2);
    const shortExplicit = argument.slice(2);
    for (const [optionString, action] of this.optionMap) {
      if (optionString === shortPrefix) {
        matches.push({ action, optionString, explicitArgument: shortExplicit });
      } else if (optionString.startsWith(argument)) {
        matches.push({ action, optionString, explicitArgument: null });
      }
    }
    return matches;
  }
}

