/**
 * UTF-8 offset arithmetic, done by hand.
 *
 * Two places need to reason about byte counts rather than character counts: the
 * traceback anchor columns, which CPython records as byte offsets into a source
 * line, and partial writes, which report progress in bytes.
 */

/** Number of UTF-8 bytes a single code point occupies. */
export function utf8Size(codePoint) {
  if (codePoint < 0x80) return 1;
  if (codePoint < 0x800) return 2;
  if (codePoint < 0x10000) return 3;
  return 4;
}

/** UTF-8 byte length of a string. */
export function utf8ByteLength(text) {
  let bytes = 0;
  for (const character of text) bytes += utf8Size(character.codePointAt(0));
  return bytes;
}

/**
 * `_byte_offset_to_character_offset`: how many characters of `text` fit within
 * its first `byteOffset` UTF-8 bytes.  Offsets past the end clamp to the whole
 * string.
 */
export function byteOffsetToCharOffset(text, byteOffset) {
  let bytes = 0;
  let characters = 0;
  for (const character of text) {
    const size = utf8Size(character.codePointAt(0));
    if (bytes + size > byteOffset) break;
    bytes += size;
    characters += 1;
  }
  return characters;
}

/** The remainder of `text` after its first `byteOffset` UTF-8 bytes. */
export function sliceFromByteOffset(text, byteOffset) {
  const characters = Array.from(text);
  let bytes = 0;
  let index = 0;
  while (index < characters.length) {
    const size = utf8Size(characters[index].codePointAt(0));
    if (bytes + size > byteOffset) break;
    bytes += size;
    index += 1;
  }
  return characters.slice(index).join('');
}

