/**
 * Synchronous stdio writers.
 *
 * `process.stdout.write` is asynchronous when stdout is a pipe, so anything
 * written just before `process.exit()` can be lost.  Several code paths here end
 * in an immediate exit, so all output goes through `writeSync` instead; the
 * bytes are therefore identical to what `print()` and CPython's traceback
 * machinery would emit, just flushed eagerly.
 */

import { writeSync } from 'node:fs';

import { sliceFromByteOffset, utf8ByteLength } from './utf8.mjs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function write(fileDescriptor, text) {
  let remaining = text;
  while (remaining.length > 0) {
    let written;
    try {
      written = writeSync(fileDescriptor, remaining);
    } catch (error) {
      // A non-blocking pipe that is momentarily full: retry.
      if (error.code === 'EAGAIN') continue;
      // Broken pipe, full disk, closed descriptor: CPython reports the failure
      // but still exits with the status it had chosen, so the write is dropped
      // rather than escalated.
      return;
    }
    if (written >= utf8ByteLength(remaining)) return;
    remaining = sliceFromByteOffset(remaining, written);
  }
}

export function writeStdout(text) {
  write(STDOUT_FD, text);
}

export function writeStderr(text) {
  write(STDERR_FD, text);
}

