import { runAll } from './difftest.mjs';
const W20 = Array.from({ length: 20 }, (_, i) => i + 1).join(',');
const W32 = Array.from({ length: 32 }, (_, i) => i + 1).join(',');
const cases = [];
// Every printable ASCII character as a 1-char hrp, plus as part of a 3-char hrp.
for (let cp = 0x01; cp <= 0x7f; cp++) {
  const ch = String.fromCodePoint(cp);
  cases.push(['--a', ch, '--b', '5', '--c', W20]);
  cases.push(['--a', `a${ch}b`, '--b', '0', '--c', W20]);
}
// Non-ASCII hrps.
for (const hrp of ['é', 'ébc', 'bcé', 'ß', 'İ', 'ı', 'Σ', 'σ', 'ς', 'ẛ', 'ﬀ', '中文',
  '\u{1f600}', 'a\u{1f600}b', 'é', 'Á', 'ß', 'ẞ', 'ǅ', 'ǆ', 'Ǆ',
  'İ', 'ı', 'ﬀ', 'K', 'ſ', 'K', 'k']) {
  cases.push(['--a', hrp, '--b', '5', '--c', W20]);
  cases.push(['--a', hrp, '--b', '0', '--c', W32]);
}
// Case variations.
for (const hrp of ['BC', 'Bc', 'bC', 'TEST', 'tesT', 'A1B', 'a1B', 'X', 'x', 'B1C']) {
  cases.push(['--a', hrp, '--b', '5', '--c', W20]);
  cases.push(['--a', hrp, '--b', '0', '--c', W20]);
}
// hrp lengths 1..80.
for (let n = 1; n <= 80; n++) {
  cases.push(['--a', 'q'.repeat(n), '--b', '5', '--c', W20]);
}
// hrps containing the separator and digits.
for (const hrp of ['1', '11', '1a', 'a1', 'a1b', 'a11b', '111', 'a1b1c', '0', '9']) {
  cases.push(['--a', hrp, '--b', '5', '--c', W20]);
}
// The None boundary: witness version x program length.
for (let ver = -3; ver <= 18; ver++) {
  for (const len of [1, 2, 3, 19, 20, 21, 31, 32, 33, 39, 40, 41]) {
    const prog = Array.from({ length: len }, (_, i) => (i * 7 + 1) % 256).join(',');
    cases.push(['--a', 'bc', `--b=${ver}`, `--c=${prog}`]);
  }
}
await runAll(cases, { label: 'hrp-boundary' });

